// 띠 왼쪽에 사는 작은 Clawd(Claude Code 마스코트). `$` 를 받지 않는다 — 상태와 시각(ms)만으로 한 프레임을 만든다.
// 모양은 Claude Code 시작 화면의 Clawd 를 반 칸 단위 점(가로 18 × 세로 6)으로 옮긴 것이다. 점 그림을 다시
// 사분면 블록 글자(▛ ▜ ▝ …)로 묶어 그리므로 반 칸씩 옮겨도 모양이 깨지지 않는다(종종걸음 · 반 줄 깡충 · 화면 밖으로 나가기).
// 가만히 선 자세(x 짝수 · y 0)는 시작 화면의 글자와 똑같이 나온다. 돌아서는 모습은 시작 화면 애니메이션의 글자를 그대로 쓴다.

export const CLAWD_COLS = 15
export const CLAWD_ROWS = 3
export const CLAWD_TICK_MS = 150

const W = CLAWD_COLS * 2
const H = CLAWD_ROWS * 2
const SW = 18
const SH = 6
// 다 보이는 채로 설 수 있는 x 범위(반 칸 단위).
const X_MAX = W - SW
const X_MID = X_MAX / 2
// Claude Code 테마의 clawd_body · clawd_background 값.
const BODY = 0xd77757
const EYE = 0x000000
const DEF = 0x01000000
// 주변 효과의 색. 그림 칸은 테마를 따라가지 못하므로 밝은 바탕 · 어두운 바탕 어디서나 읽히는 중간 밝기만 쓴다(2026-10-08).
const YELLOW = 0xe0a100
const RED = 0xf0506e
const CYAN = 0x2fa8e0
const GRAY = 0x8a8a8a
const STEAM = 0x9aa3b2
// 맥 자원 단계별 몸 색: 평소 → 주의 → 높음 → 위험. 잠들면 조금 가라앉은 색.
export const HEAT_COLORS = [BODY, 0xe2643c, 0xee4b2b, 0xc22a1e]
const SLEEP_BODY = 0xa85f48
// 우울할 때의 몸 색(자원 단계가 평소일 때만).
const GLOOM_BODY = 0x8c98b3
// 한 칸의 네 점(왼위 8 · 오른위 4 · 왼아래 2 · 오른아래 1) → 사분면 블록 글자.
const QUAD = [' ', '▗', '▖', '▄', '▝', '▐', '▞', '▟', '▘', '▚', '▌', '▙', '▀', '▜', '▛', '█']
const UNQUAD = new Map(QUAD.map((ch, bits) => [ch, bits]))

// ── 모양 ────────────────────────────────────────────────────────────────────────
// 머리 두 줄에서 양옆이 몸으로 막힌 빈 점을 눈으로 본다(검은 바탕으로 칠할 자리).
function withEyes(on) {
  const eye = new Uint8Array(SW * SH)
  for (const y of [0, 1]) {
    let first = -1
    let last = -1
    for (let x = 0; x < SW; x += 1) {
      if (on[y * SW + x]) {
        if (first < 0) first = x
        last = x
      }
    }
    for (let x = first + 1; x < last; x += 1) if (!on[y * SW + x]) eye[y * SW + x] = 1
  }
  return { s: on, e: eye }
}

const poseCache = new Map()

// eyes: -1 왼쪽 0 정면 1 오른쪽 · eyeUp: 위를 봄 · blink: 두 눈 감음 · wink: 'L' | 'R' 한쪽만 감음 · shades: 선글라스(눈 줄에 검은 알 두 개)
// armL / armR: 'down' | 'up' · legs: 0 | 1 (번갈아 쓰면 종종걸음)
function pose(over) {
  const p = Object.assign({ eyes: 0, eyeUp: false, blink: false, wink: '', shades: false, armL: 'down', armR: 'down', legs: 0 }, over || {})
  const key = JSON.stringify(p)
  if (poseCache.has(key)) return poseCache.get(key)
  const on = new Uint8Array(SW * SH)
  const put = (x, y) => {
    on[y * SW + x] = 1
  }
  for (let x = 3; x <= 15; x += 1) for (const y of [0, 1, 2, 3]) put(x, y)
  const ey = p.eyeUp ? 0 : 1
  if (!p.blink && p.wink !== 'L') on[ey * SW + 5 + p.eyes] = 0
  if (!p.blink && p.wink !== 'R') on[ey * SW + 13 + p.eyes] = 0
  // 선글라스: 눈 줄을 가로지르는 검은 알 두 개(가운데 한 점은 코걸이로 남긴다). 눈 위치 · 깜빡임과 상관없이 덮는다.
  if (p.shades) for (let x = 4; x <= 14; x += 1) if (x !== 9) on[1 * SW + x] = 0
  // 팔: 내리면 몸통 줄에서 옆으로, 올리면 한 줄 위로 꺾인다.
  for (const [x, y] of p.armL === 'up' ? [[1, 1], [2, 1], [2, 2]] : [[1, 2], [2, 2]]) put(x, y)
  for (const [x, y] of p.armR === 'up' ? [[16, 1], [17, 1], [16, 2]] : [[16, 2], [17, 2]]) put(x, y)
  for (const x of p.legs ? [4, 6, 12, 14] : [3, 5, 13, 15]) put(x, 4)
  const sp = withEyes(on)
  poseCache.set(key, sp)
  return sp
}

// 시작 화면 애니메이션의 「돌아서는」 글자들(Claude Code 2.1.293 에서 옮김).
const TURN_GLYPHS = {
  r12: [' ▐█▜██▛█ ', '▝▜██████▀', ' ▝▝   ▝▝ '],
  r30: ['  █▛██▛▌ ', ' ▝█████▛ ', '  ▘▘  ▘▘ '],
  r55: ['  ▐█▛█▜  ', '  ▐████  ', '  ▝▝ ▝▝  '],
  r75: ['   ██▛▌  ', '   ███▌  ', '   ▘  ▘  '],
  edge: ['   ▐██   ', '   ▐██   ', '   ▝ ▝   '],
  b105: ['   ███▌  ', '   ███▌  ', '   ▘  ▘  '],
  b125: ['  ▐████  ', '  ▐████  ', '  ▝▝ ▝▝  '],
  b150: ['  █████▌ ', ' ▝█████▛ ', '  ▘▘  ▘▘ '],
  back: [' ▐██████ ', '▝▜██████▀', ' ▝▝   ▝▝ '],
  l75: ['   ▛██▌  ', '   ███▌  ', '   ▘  ▘  '],
  l55: ['  ▐▜▛██  ', '  ▐████  ', '  ▝▝ ▝▝  '],
  l30: ['  ▛██▛█▌ ', ' ▝█████▛ ', '  ▘▘  ▘▘ '],
  l12: [' ▐▛███▜█ ', '▝▜██████▀', ' ▝▝   ▝▝ '],
}
// 한 바퀴. 뒤돌아선 뒤 반대쪽으로 도는 구간은 같은 그림을 좌우로 뒤집어 쓴다.
const SPIN = [['r12'], ['r30'], ['r55'], ['r75'], ['edge'], ['b105'], ['b125'], ['b150'], ['back'], ['b150', true], ['b125', true], ['b105', true], ['edge', true], ['l75'], ['l55'], ['l30'], ['l12']]

const turnCache = new Map()

function turn(name, flip) {
  const key = name + (flip ? '~' : '')
  if (turnCache.has(key)) return turnCache.get(key)
  const on = new Uint8Array(SW * SH)
  TURN_GLYPHS[name].forEach((row, cy) => {
    ;[...row].forEach((ch, cx) => {
      const bits = UNQUAD.get(ch) || 0
      const set = (dx, dy) => {
        const x = cx * 2 + dx
        on[(cy * 2 + dy) * SW + (flip ? SW - 1 - x : x)] = 1
      }
      if (bits & 8) set(0, 0)
      if (bits & 4) set(1, 0)
      if (bits & 2) set(0, 1)
      if (bits & 1) set(1, 1)
    })
  })
  const sp = withEyes(on)
  turnCache.set(key, sp)
  return sp
}

// 한 프레임 = 모양(s · e) + 자리(x: 반 칸 좌우, y: 반 줄 아래로) + 주변 효과(fx: 빈 칸에만 그리는 글자).
function fr(x, y, over, fx) {
  const sp = pose(over)
  return { s: sp.s, e: sp.e, x, y, fx: fx || [], over: over || {} }
}

// 같은 자세에 선글라스만 씌운 프레임. 돌아서는 그림(tf)은 얼굴이 정면이 아니라 그대로 둔다.
const shadedCache = new WeakMap()
function shaded(f) {
  if (!f.over) return f
  if (!shadedCache.has(f)) {
    const sp = pose(Object.assign({}, f.over, { shades: true, eyeUp: false }))
    shadedCache.set(f, Object.assign({}, f, { s: sp.s, e: sp.e }))
  }
  return shadedCache.get(f)
}

function tf(name, flip, x) {
  const sp = turn(name, flip)
  return { s: sp.s, e: sp.e, x, y: 0, fx: [] }
}

// 몸 바로 오른쪽 · 왼쪽 빈 칸의 열 번호.
function right(x) {
  return Math.floor((x + SW) / 2)
}
function left(x) {
  return Math.floor((x + 1) / 2) - 1
}
function mark(cx, cy, ch, color) {
  return { cx, cy, ch, color }
}

// ── 동작 조각 ────────────────────────────────────────────────────────────────────
function repeat(n, frames) {
  const out = []
  for (let i = 0; i < n; i += 1) out.push(...frames)
  return out
}
const clampX = (x) => Math.max(0, Math.min(X_MAX, x))

const look = (x) => [fr(x, 0, { eyes: -1 }), fr(x, 0, { eyes: -1 }), fr(x, 0, { eyes: 1 }), fr(x, 0, { eyes: 1 }), fr(x, 0, { eyeUp: true }), fr(x, 0)]
const hop = (x, n) => repeat(n, [fr(x, 1), fr(x, 0, { armL: 'up', armR: 'up' })])
const wave = (x) => repeat(3, [fr(x, 0, { armR: 'up' }), fr(x, 0, { armL: 'up' })])
const stomp = (x) => repeat(3, [fr(x, 0, { legs: 1 }), fr(x, 0)])
const blink = (x) => [fr(x, 0, { blink: true }), fr(x, 0), fr(x, 0, { blink: true }), fr(x, 0)]
const wink = (x) => [fr(x, 0, { wink: 'R' }), fr(x, 0, { wink: 'R', armR: 'up' }), fr(x, 0)]
const spin = (x) => SPIN.map(([name, flip]) => tf(name, flip, x))
const shiver = (x) => repeat(3, [fr(clampX(x - 1), 0, { blink: true }), fr(clampX(x + 1), 0, { blink: true })])
const dance = (x) =>
  repeat(2, [
    fr(clampX(x - 1), 0, { armL: 'up', legs: 1, eyes: -1 }),
    fr(clampX(x - 1), 1, { armL: 'up' }),
    fr(clampX(x + 1), 0, { armR: 'up', legs: 1, eyes: 1 }),
    fr(clampX(x + 1), 1, { armR: 'up' }),
  ])

// 한 발짝씩 종종걸음.
function walk(from, to) {
  const out = []
  const dir = to > from ? 1 : -1
  for (let x = from + dir, i = 0; dir > 0 ? x <= to : x >= to; x += dir, i += 1) out.push(fr(x, 0, { eyes: dir, legs: i % 2 }))
  return out
}

// 먼지를 날리며 내달린다. 화면 밖 좌표까지 갈 수 있다(잘려 보인다).
function dash(from, to) {
  const out = []
  const dir = to > from ? 1 : -1
  for (let x = from + dir * 3, i = 0; dir > 0 ? x <= to : x >= to; x += dir * 3, i += 1) {
    const behind = dir > 0 ? left(x) : right(x)
    out.push(fr(x, i % 2, { eyes: dir, legs: i % 2, armL: i % 2 ? 'up' : 'down', armR: i % 2 ? 'down' : 'up' }, [mark(behind, 2, i % 2 ? '⠐' : '⠂', GRAY)]))
  }
  out.push(fr(to, 0, { eyes: dir }))
  return out
}

// 아래로 쏙 숨었다가 까꿍.
const peekaboo = (x) => [
  fr(x, 1),
  fr(x, 3),
  fr(x, 5),
  fr(x, 7),
  fr(x, 7),
  fr(x, 7),
  fr(x, 4, { armL: 'up', armR: 'up' }),
  fr(x, 0, { armL: 'up', armR: 'up' }, [mark(right(x), 0, '*', YELLOW)]),
  fr(x, 1, { armL: 'up', armR: 'up' }),
  fr(x, 0),
]

// 오른쪽 밖으로 뛰쳐나갔다가 왼쪽에서 다시 들어온다.
const lap = (x) => [...dash(x, W + 2), ...dash(-SW - 2, X_MID)]

// 반짝이를 뿌리며 만세.
function sparkle(x, n) {
  const out = []
  for (let i = 0; i < n; i += 1) {
    const fx = [mark(i % 2 ? right(x) : left(x), i % 3, i % 2 ? '*' : '+', YELLOW), mark(i % 2 ? left(x) : right(x), (i + 1) % 3, '.', YELLOW)]
    out.push(fr(x, i % 2, { armL: 'up', armR: 'up', legs: i % 2 }, fx))
  }
  return out
}

// 동전을 보고 달려가 폴짝 뛰어 먹는다.
function coin(x) {
  const stop = X_MAX - 4
  const cx = right(stop)
  const c = [mark(cx, 1, '▄', YELLOW)]
  const out = [fr(x, 0, { eyes: 1 }, c), fr(x, 0, { eyes: 1, eyeUp: false, armL: 'up' }, c)]
  for (const f of walk(x, stop)) out.push(Object.assign({}, f, { fx: c }))
  out.push(fr(stop, 1, { eyes: 1 }, c), fr(stop, 0, { eyes: 1, armR: 'up' }, [mark(cx, 0, '+', YELLOW)]), fr(stop, 0, { armL: 'up', armR: 'up' }, [mark(cx, 0, '*', YELLOW)]), fr(stop, 1), fr(stop, 0))
  return out
}

// ── 안무 ────────────────────────────────────────────────────────────────────────
// 쉬는 동안: 동작 조각을 정해진 씨앗으로 섞어 길게 잇는다(같은 순서가 금방 되풀이되지 않게). 조각 사이는 걸어서 옮긴다.
function idlePlaylist() {
  let seed = 20261008
  const rnd = (n) => {
    seed = (seed * 1664525 + 1013904223) >>> 0
    return seed % n
  }
  const bits = [look, (x) => hop(x, 2), wave, stomp, blink, wink, spin, shiver, dance, peekaboo, (x) => sparkle(x, 4), coin, lap, (x) => hop(x, 1)]
  const out = []
  let x = X_MID
  for (let round = 0; round < 3; round += 1) {
    const order = bits.map((b, i) => i)
    for (let i = order.length - 1; i > 0; i -= 1) {
      const j = rnd(i + 1)
      ;[order[i], order[j]] = [order[j], order[i]]
    }
    for (const i of order) {
      const frames = bits[i](x)
      out.push(...frames)
      x = clampX(frames[frames.length - 1].x)
      // 다음 조각을 할 자리로 걸어간다.
      const next = rnd(X_MAX + 1)
      out.push(...walk(x, next))
      x = next
    }
  }
  out.push(...walk(x, X_MID))
  return out
}

const HOME = X_MID

const IDLE = idlePlaylist()

// 턴이 도는 동안 — 지금 하는 일에 따라 다르게 논다.
const LOOPS = {
  // 생각 중(툴 없음): 왔다 갔다 서성인다.
  think: [...walk(HOME, X_MAX), ...look(X_MAX), ...walk(X_MAX, 0), ...look(0), ...walk(0, HOME), ...hop(HOME, 1)],
  // 읽는 중: 눈으로 줄을 훑고, 가끔 갸웃(?).
  read: [
    fr(HOME, 0, { eyes: -1 }),
    fr(HOME, 0, { eyes: -1 }),
    fr(HOME, 0),
    fr(HOME, 0, { eyes: 1 }),
    fr(HOME, 1, { eyes: 1 }),
    fr(HOME, 0, { eyes: -1 }),
    fr(HOME, 0),
    fr(HOME, 0, { eyes: 1 }),
    fr(HOME, 0, { eyeUp: true }, [mark(right(HOME), 0, '?', CYAN)]),
    fr(HOME, 0, { eyeUp: true }, [mark(right(HOME), 0, '?', CYAN)]),
    fr(HOME, 1, { blink: true }),
    fr(HOME, 0),
  ],
  // 고치는 중: 오른팔로 뚝딱뚝딱, 내려칠 때 불꽃.
  edit: [
    fr(HOME, 0, { armR: 'up', eyes: 1 }),
    fr(HOME, 1, { eyes: 1 }, [mark(right(HOME), 2, '*', YELLOW)]),
    fr(HOME, 0, { armR: 'up', eyes: 1 }),
    fr(HOME, 1, { eyes: 1 }, [mark(right(HOME), 1, '.', YELLOW)]),
    fr(HOME, 0, { armR: 'up', eyes: 1, legs: 1 }),
    fr(HOME, 1, { eyes: 1 }, [mark(right(HOME), 2, '+', YELLOW)]),
    fr(HOME, 0, { armR: 'up', blink: true }),
    fr(HOME, 1, { eyes: 1 }, [mark(right(HOME), 2, '*', YELLOW)]),
  ],
  // 명령 · 테스트 실행 중: 제자리 전력 질주.
  run: [
    fr(HOME, 0, { legs: 0, armL: 'up', eyes: 1 }, [mark(left(HOME), 2, '⠐', GRAY)]),
    fr(HOME + 1, 1, { legs: 1, armR: 'up', eyes: 1 }, [mark(left(HOME + 1), 2, '⠂', GRAY)]),
    fr(HOME, 0, { legs: 0, armL: 'up', eyes: 1 }, [mark(left(HOME) - 1, 2, '⠐', GRAY)]),
    fr(HOME - 1, 1, { legs: 1, armR: 'up', eyes: 1 }, [mark(left(HOME - 1), 2, '⠂', GRAY)]),
  ],
  // 사용자 답을 기다리는 중: 두 팔 들고 뛰며 빨간 느낌표를 깜빡인다.
  wait: [
    fr(HOME, 0, { armL: 'up', armR: 'up' }, [mark(right(HOME), 0, '!', RED)]),
    fr(HOME, 1, {}, [mark(right(HOME), 0, '!', RED)]),
    fr(HOME, 0, { armL: 'up', armR: 'up' }),
    fr(HOME, 1, { blink: true }),
  ],
}

// 한 번만 하는 동작. since(그 일이 일어난 뒤 지난 시간)로 프레임을 고른다.
const ONCE = {
  // 턴이 막 끝남: 반짝이 만세 → 한 바퀴.
  cheer: [...sparkle(HOME, 8), ...spin(HOME), ...hop(HOME, 1)],
  // 명령이 실패함: 깜짝 놀라 부르르.
  startle: [
    fr(HOME, 0, { armL: 'up', armR: 'up', eyeUp: true }, [mark(right(HOME), 0, '!', RED)]),
    fr(HOME, 0, { armL: 'up', armR: 'up', eyeUp: true }, [mark(right(HOME), 0, '!', RED)]),
    ...shiver(HOME).map((f) => Object.assign({}, f, { fx: [mark(right(f.x), 0, '!', RED)] })),
    fr(HOME, 1, { blink: true }),
    fr(HOME, 0),
  ],
  // 프롬프트를 받음: 「넵!」 하고 폴짝.
  // 1.35초. 처음에는 0.75초였는데 짧아서 눈에 안 띄었다.
  salute: [
    fr(HOME, 1),
    fr(HOME, 0, { armR: 'up' }),
    fr(HOME, 0, { armR: 'up' }),
    fr(HOME, 1, { armR: 'up' }),
    fr(HOME, 0, { armR: 'up' }),
    fr(HOME, 0, { armR: 'up' }),
    fr(HOME, 1, { armR: 'up', blink: true }),
    fr(HOME, 0, { armR: 'up' }),
    fr(HOME, 0),
  ],
  // 커밋 · 푸시 성공: 동전 먹기.
  coin: coin(2),
  // 정해진 시각(설정의 bells · 평일): 두 팔을 번갈아 들며 좌우로 흔들고 음표를 날린다. 글자는 띄우지 않는다.
  bell: repeat(4, [
    fr(HOME - 1, 0, { armL: 'up', eyes: -1 }, [mark(left(HOME - 1), 0, '♪', YELLOW)]),
    fr(HOME, 0, { armL: 'up', armR: 'up' }),
    fr(HOME + 1, 0, { armR: 'up', eyes: 1 }, [mark(right(HOME + 1), 0, '♪', YELLOW)]),
    fr(HOME, 1, { armL: 'up', armR: 'up', blink: true }),
  ]),
}

// 오래 쉰 세션: 눈을 감고 반 줄 내려앉아 잔다. 1초에 한 장씩만 넘긴다(잠든 세션은 그림도 1초에 한 번 그린다).
const SLEEP = [
  fr(HOME, 1, { blink: true }),
  fr(HOME, 1, { blink: true }, [mark(right(HOME), 1, 'z', GRAY)]),
  fr(HOME, 1, { blink: true }, [mark(right(HOME), 1, 'z', GRAY), mark(right(HOME) + 1, 0, 'z', GRAY)]),
  fr(HOME, 1, { blink: true }, [mark(right(HOME) + 1, 0, 'z', GRAY)]),
]

// 조는 중(5분 넘게 쉼): 눈이 감기며 고개가 떨어졌다가 화들짝 깬다. 한 장에 0.45초씩 천천히 넘긴다.
export const DOZE_TICK_MS = 450
const DOZE = [
  fr(HOME, 0),
  fr(HOME, 0),
  fr(HOME, 0, { blink: true }),
  fr(HOME, 1, { blink: true }),
  fr(HOME, 1, { blink: true }),
  fr(HOME, 1, { blink: true }),
  fr(HOME, 0, { eyeUp: true }),
  fr(HOME, 0),
  fr(HOME, 0, { blink: true }),
  fr(HOME, 1, { blink: true }),
  fr(HOME, 1, { blink: true }),
  fr(HOME, 1, { blink: true }),
  fr(HOME, 1, { blink: true }),
  fr(HOME, 0, { eyes: -1 }),
  fr(HOME, 0, { eyes: 1 }),
]

// 퇴근 5분 전 ~ 5분 뒤: 선글라스를 쓰고 춤춘다. 음표가 날린다.
const SHADES = { shades: true }
const PARTY = repeat(2, [
  fr(HOME - 1, 0, Object.assign({ armL: 'up', legs: 1 }, SHADES), [mark(left(HOME - 1), 0, '♪', YELLOW)]),
  fr(HOME - 1, 1, Object.assign({ armL: 'up' }, SHADES), [mark(left(HOME - 1), 0, '♪', YELLOW)]),
  fr(HOME + 1, 0, Object.assign({ armR: 'up', legs: 1 }, SHADES), [mark(right(HOME + 1), 0, '♪', YELLOW)]),
  fr(HOME + 1, 1, Object.assign({ armR: 'up' }, SHADES), [mark(right(HOME + 1), 0, '♪', YELLOW)]),
  fr(HOME, 0, Object.assign({ armL: 'up', armR: 'up' }, SHADES)),
  fr(HOME, 1, Object.assign({}, SHADES)),
  fr(HOME, 0, Object.assign({ armL: 'up', armR: 'up', legs: 1 }, SHADES)),
  fr(HOME, 1, Object.assign({}, SHADES)),
])

// 퇴근 5분 뒤 ~ 1시간 뒤: 주저앉아 한숨 쉬고 눈물 한 방울. 한 장에 0.45초씩 천천히 넘긴다.
const GLOOM = [
  fr(HOME, 1, { eyes: -1 }),
  fr(HOME, 1, { eyes: -1 }),
  fr(HOME, 1, { blink: true }),
  fr(HOME, 1, { blink: true }, [mark(right(HOME), 1, '.', GRAY)]),
  fr(HOME, 1, { blink: true }, [mark(right(HOME), 1, '.', GRAY), mark(right(HOME) + 1, 0, '.', GRAY)]),
  fr(HOME, 1, { eyes: 1 }),
  fr(HOME, 1, { eyes: 1 }),
  fr(HOME, 1, { blink: true }, [mark(left(HOME), 1, "'", CYAN)]),
  fr(HOME, 1, { blink: true }, [mark(left(HOME), 2, "'", CYAN)]),
  fr(HOME, 1),
]

const within = (since, frames) => since >= 0 && since < frames.length * CLAWD_TICK_MS
const at = (frames, since) => frames[Math.min(frames.length - 1, Math.floor(since / CLAWD_TICK_MS))]

// st: { asking, busy, activity: 'think' | 'read' | 'edit' | 'run', sinceDone, sinceErr, sinceSubmit, sinceCoin, sinceBell, hot, heat, asleep }
// since* 는 그 일이 일어난 뒤 지난 ms(없었으면 -1). hot 은 컨텍스트나 5시간 한도가 85% 이상일 때 — 땀을 흘린다.
// heat 는 맥 자원 단계(0 평소 · 1 주의 · 2 높음 · 3 위험) — 몸 색과 땀 · 김 · 떨림으로 보인다. asleep 은 오래 쉰 세션.
export function clawdScene(st) {
  if (st.asking) return 'wait'
  if (within(st.sinceErr, ONCE.startle)) return 'startle'
  if (within(st.sinceCoin, ONCE.coin)) return 'coin'
  if (within(st.sinceBell, ONCE.bell)) return 'bell'
  // 엔터 「넵」 은 턴이 시작됐는지와 상관없이 재생한다 — 프롬프트 훅이 오래 걸리면 턴 시작이 1초 넘게 늦어,
  // 「작업 중일 때만」 으로 걸어 두면 재생 창이 지난 뒤라 한 번도 보이지 않았다.
  if (within(st.sinceSubmit, ONCE.salute)) return 'salute'
  if (st.busy) return LOOPS[st.activity] ? st.activity : 'think'
  if (within(st.sinceDone, ONCE.cheer)) return 'cheer'
  // 퇴근 무렵의 기분(st.mood): 신날 때는 자던 세션도 일어나 춤추고, 우울은 잠든 세션에는 걸지 않는다.
  if (st.mood === 'party') return 'party'
  if (st.asleep) return 'sleep'
  if (st.mood === 'gloom') return 'gloom'
  if (st.dozing) return 'doze'
  return 'idle'
}

const SINCE = { startle: 'sinceErr', coin: 'sinceCoin', salute: 'sinceSubmit', cheer: 'sinceDone', bell: 'sinceBell' }

export function clawdFrameOf(st, ms) {
  const scene = clawdScene(st)
  const tick = Math.floor(Math.max(0, ms) / CLAWD_TICK_MS)
  let f
  if (scene === 'idle') f = IDLE[tick % IDLE.length]
  else if (scene === 'sleep') f = SLEEP[Math.floor(Math.max(0, ms) / 1000) % SLEEP.length]
  else if (scene === 'doze') f = DOZE[Math.floor(Math.max(0, ms) / DOZE_TICK_MS) % DOZE.length]
  else if (scene === 'gloom') f = GLOOM[Math.floor(Math.max(0, ms) / DOZE_TICK_MS) % GLOOM.length]
  else if (scene === 'party') f = PARTY[tick % PARTY.length]
  else if (ONCE[scene]) f = at(ONCE[scene], st[SINCE[scene]])
  else f = LOOPS[scene][tick % LOOPS[scene].length]
  // 신나는 시간에는 일하는 중에도 선글라스를 쓴다.
  if (st.mood === 'party' && scene !== 'party') f = shaded(f)
  const heat = Math.max(0, Math.min(3, st.heat || 0))
  // 위험: 좌우로 떤다(자는 동안은 떨지 않는다).
  if (heat >= 3 && scene !== 'sleep') f = Object.assign({}, f, { x: clampX(f.x + (tick % 2 ? 1 : -1)) })
  const fx = [...f.fx]
  const free = (cx, cy) => !fx.some((m) => m.cx === cx && m.cy === cy)
  // 땀: 한도 85% 이상이거나 자원이 주의 · 높음일 때 머리 옆에 한 방울.
  if ((st.hot || heat === 1 || heat === 2) && tick % 8 < 4 && f.y === 0 && free(right(f.x), 0)) fx.push(mark(right(f.x), 0, "'", CYAN))
  // 김: 높음이면 한 줄기, 위험이면 양쪽 두 줄기. 위아래로 번갈아 놓아 피어오르는 것처럼 보인다.
  if (heat >= 2 && scene !== 'sleep') {
    const up = tick % 6 < 3 ? 0 : 1
    if (free(left(f.x), up)) fx.push(mark(left(f.x), up, '~', STEAM))
    if (heat >= 3 && free(right(f.x) + 1, 1 - up)) fx.push(mark(right(f.x) + 1, 1 - up, '~', STEAM))
  }
  const body = heat !== 0 ? HEAT_COLORS[heat] : scene === 'sleep' ? SLEEP_BODY : scene === 'gloom' ? GLOOM_BODY : HEAT_COLORS[0]
  return Object.assign({}, f, { fx, body })
}

// ── 그리기 ──────────────────────────────────────────────────────────────────────
// 프레임 → 화면 점 그림. 화면 밖으로 나간 점은 잘린다.
function compose(f) {
  const on = new Uint8Array(W * H)
  const eye = new Uint8Array(W * H)
  for (let sy = 0; sy < SH; sy += 1) {
    const y = sy + f.y
    if (y < 0 || y >= H) continue
    for (let sx = 0; sx < SW; sx += 1) {
      const x = sx + f.x
      if (x < 0 || x >= W) continue
      if (f.s[sy * SW + sx]) on[y * W + x] = 1
      if (f.e[sy * SW + sx]) eye[y * W + x] = 1
    }
  }
  return { on, eye }
}

// 하늘 장식: 빈 칸에만 놓는다. 밤에는 별, 아침 · 낮에는 작은 구름.
const STARS = [
  [1, 0, '.'],
  [6, 0, '·'],
  [14, 1, '*'],
  [10, 1, '.'],
  [3, 2, '·'],
  [13, 2, '.'],
]
const CLOUD = [
  [1, 1, '▂'],
  [2, 1, '▃'],
  [3, 1, '▂'],
]

// 하늘 바탕 위에서 주변 효과 글자가 묻히지 않게 한다 — 대비가 2 에 못 미치면 밝은 바탕에서는 남색, 어두운 바탕에서는 흰색으로 바꾼다.
function lum(c) {
  const ch = (v) => (v / 255 <= 0.03928 ? v / 255 / 12.92 : Math.pow((v / 255 + 0.055) / 1.055, 2.4))
  return 0.2126 * ch((c >> 16) & 255) + 0.7152 * ch((c >> 8) & 255) + 0.0722 * ch(c & 255)
}
export function onSky(color, bg) {
  const a = lum(color)
  const b = lum(bg)
  const ratio = (Math.max(a, b) + 0.05) / (Math.min(a, b) + 0.05)
  if (ratio >= 2) return color
  return b > 0.25 ? 0x1b2452 : 0xffffff
}

// 프레임 → 칸마다 { ch, fg, bg }. sky: skyOf 의 결과에 showOrb(해 · 달도 그릴지)를 얹은 것 — 없으면 터미널 바탕 그대로.
function cellsOf(f, sky) {
  const { on, eye } = compose(f)
  const cells = []
  const back = (cy) => (sky ? sky.rows[cy] : DEF)
  for (let cy = 0; cy < CLAWD_ROWS; cy += 1) {
    for (let cx = 0; cx < CLAWD_COLS; cx += 1) {
      const i = (dx, dy) => (cy * 2 + dy) * W + cx * 2 + dx
      const bits = on[i(0, 0)] * 8 + on[i(1, 0)] * 4 + on[i(0, 1)] * 2 + on[i(1, 1)]
      const hasEye = eye[i(0, 0)] || eye[i(1, 0)] || eye[i(0, 1)] || eye[i(1, 1)]
      cells.push({ ch: QUAD[bits], fg: bits ? f.body || BODY : DEF, bg: hasEye && bits ? EYE : back(cy), empty: bits === 0 && !hasEye })
    }
  }
  if (sky) {
    // 노을: 맨 아랫줄 빈 칸에 주황 빛줄기.
    if (sky.glow) {
      for (let cx = 0; cx < CLAWD_COLS; cx += 1) {
        const c = cells[(CLAWD_ROWS - 1) * CLAWD_COLS + cx]
        if (c.empty) Object.assign(c, { ch: '▁', fg: 0xf0a35a })
      }
    }
    for (const [cx, cy, ch] of sky.stars ? STARS : sky.cloud ? CLOUD : []) {
      const c = cells[cy * CLAWD_COLS + cx]
      if (c.empty) Object.assign(c, { ch, fg: 0xffffff })
    }
    // 해 · 달은 반원이 같은 것을 보여 주므로, 반원이 안 보이는 좁은 폭에서만 그린다.
    if (sky.showOrb && sky.orb) {
      const c = cells[sky.orb.cy * CLAWD_COLS + Math.max(0, Math.min(CLAWD_COLS - 1, sky.orb.cx))]
      if (c.empty) Object.assign(c, { ch: sky.orb.ch, fg: sky.orb.color })
    }
  }
  // 주변 효과는 몸이 없는 칸에만 그린다(하늘 장식 위에 덮어쓴다).
  for (const m of f.fx) {
    if (m.cx < 0 || m.cx >= CLAWD_COLS || m.cy < 0 || m.cy >= CLAWD_ROWS) continue
    const c = cells[m.cy * CLAWD_COLS + m.cx]
    if (c.empty) Object.assign(c, { ch: m.ch, fg: sky ? onSky(m.color, back(m.cy)) : m.color, bg: back(m.cy) })
  }
  return cells
}

// 줄마다의 글자(시험 · 눈으로 확인용).
export function clawdRows(f) {
  const cells = cellsOf(f)
  const rows = []
  for (let cy = 0; cy < CLAWD_ROWS; cy += 1) rows.push(cells.slice(cy * CLAWD_COLS, (cy + 1) * CLAWD_COLS).map((c) => c.ch).join(''))
  return rows
}

// Raster cells 에 넣을 [글자, 글자색, 바탕색] u32 배열.
export function clawdWords(f, sky) {
  const cells = cellsOf(f, sky)
  const words = new Uint32Array(cells.length * 3)
  cells.forEach((c, i) => {
    words[i * 3] = c.ch.codePointAt(0)
    words[i * 3 + 1] = c.fg
    words[i * 3 + 2] = c.bg
  })
  return words
}

export function clawdFrame(st, ms) {
  return new Uint8Array(clawdWords(clawdFrameOf(st, ms), st.sky || null).buffer).toBase64()
}

// 시험용: 가만히 선 자세와 장면별 프레임 묶음.
export function clawdRest(x) {
  return fr(x, 0)
}
export const CLAWD_SCENES = Object.assign({ idle: IDLE, sleep: SLEEP, doze: DOZE, party: PARTY, gloom: GLOOM }, LOOPS, ONCE)

files.hooks/arc.js:
// 띠 오른쪽의 반원(해 · 달이 지나는 길)과 그 안의 퇴근 숫자, 아래 주간 띠. 순수 로직 — `$` 를 받지 않는다.
// 반원은 점자 글자(한 칸에 점 2 × 4)로 찍고, 숫자는 그림 칸에 한글이 못 들어가서 ASCII 만 쓴다.

export const ARC_COLS = 14
export const ARC_ROWS = 2
// 퇴근 시각(자정부터의 분)의 기본값. 평일만 센다. 설정의 quitTime 으로 바꾼다.
export const QUIT_MIN = 18 * 60
// 정해진 시각 효과(Clawd 종)의 기본값 — 없음. 설정의 bells 로 넣는다(평일에만 울린다).
export const BELLS_DEFAULT = []
// 위치가 설정에 없을 때 쓰는 일출 · 일몰.
export const SUN_FIXED = { rise: 6 * 60, set: 18 * 60 }
export const DAY_KO = ['일', '월', '화', '수', '목', '금', '토']

const DEF = 0x01000000
const BRL = [
  [0x01, 0x08],
  [0x02, 0x10],
  [0x04, 0x20],
  [0x40, 0x80],
]
// 그림 칸의 색은 테마를 따라가지 못한다(숫자 색만 받는다). 그래서 밝은 바탕 · 어두운 바탕 어디서나 읽히는 중간 밝기만 쓴다
// (흰 바탕 · 어두운 바탕 모두에서 대비 2.4 이상).
const TC = { dim: 0x7b8491, green: 0x3fae58, lime: 0x74ad2c, yellow: 0xcf9400, orange: 0xe0762b, red: 0xf0506e, purple: 0x9b72e8 }
const MOON = 0x8f9bd9
const REST = 0x7b8491
const FLASH = 0xff6b00

// 그날의 일출 · 일몰(자정부터의 분). 위도 · 경도 · 시간대(UTC 와의 차 · 시간)를 받는다. NOAA 간이식이라 2~3분쯤 어긋날 수 있다.
export function sunTimes(year, month, day, lat, lon, tzHours) {
  const n = Math.floor((Date.UTC(year, month - 1, day) - Date.UTC(year, 0, 0)) / 86400000)
  const g = ((2 * Math.PI) / 365) * (n - 1)
  const eq = 229.18 * (0.000075 + 0.001868 * Math.cos(g) - 0.032077 * Math.sin(g) - 0.014615 * Math.cos(2 * g) - 0.040849 * Math.sin(2 * g))
  const decl =
    0.006918 - 0.399912 * Math.cos(g) + 0.070257 * Math.sin(g) - 0.006758 * Math.cos(2 * g) + 0.000907 * Math.sin(2 * g) - 0.002697 * Math.cos(3 * g) + 0.00148 * Math.sin(3 * g)
  const rad = Math.PI / 180
  const cosH = Math.cos(90.833 * rad) / (Math.cos(lat * rad) * Math.cos(decl)) - Math.tan(lat * rad) * Math.tan(decl)
  const ha = Math.acos(Math.max(-1, Math.min(1, cosH))) / rad
  const noon = 720 - 4 * lon - eq + tzHours * 60
  return { rise: Math.round(noon - 4 * ha), set: Math.round(noon + 4 * ha) }
}

// 퇴근까지 남은 시간. 주말과 퇴근 5시간 뒤부터는 표시하지 않는다(off).
// 색은 가까울수록 회색 → 초록 → 연두 → 노랑 → 주황 → 빨강. 마지막 10분과 퇴근 직후 10분은 깜빡인다.
// 남은 시간은 「4h20m」 · 「42m」 처럼 길이로 적는다 — 「4:20」 으로 적으면 지금 시각처럼 읽힌다.
// 그림 칸에 한글이 못 들어가서 퇴근 시각에는 「0m」 을 초록으로 깜빡이고, 그 뒤에는 넘긴 시간을 보라색으로 보인다.
export function quitTimer(min, dow, end = QUIT_MIN) {
  if (dow === 0 || dow === 6) return { off: true }
  const fmt = (m) => (m >= 60 ? Math.floor(m / 60) + 'h' + String(Math.floor(m % 60)).padStart(2, '0') + 'm' : Math.floor(m) + 'm')
  const rem = end - min
  if (rem <= 0) {
    const over = -rem
    if (over > 300) return { off: true }
    return over < 10 ? { text: '0m', color: TC.green, blink: true, done: true } : { text: '+' + fmt(over), color: TC.purple, blink: false, done: true }
  }
  const color = rem > 240 ? TC.dim : rem > 120 ? TC.green : rem > 60 ? TC.lime : rem > 30 ? TC.yellow : rem > 10 ? TC.orange : TC.red
  return { text: fmt(rem), color, blink: rem <= 10, done: false }
}

// 해 색: 뜰 때 주홍 → 오전 귤빛 → 한낮 호박빛 → 오후 주황 → 질 때 붉은 주황. 노랑 · 흰빛은 밝은 바탕에서 안 보여 쓰지 않는다.
export function sunColor(f) {
  return f < 0.07 ? 0xff7d52 : f < 0.22 ? 0xf08a24 : f < 0.62 ? 0xe08a00 : f < 0.8 ? 0xe8801a : f < 0.93 ? 0xf07030 : 0xff6336
}

// 반원 위에서 해(낮) · 달(밤)이 지금 어디쯤인지(0 왼쪽 끝 ~ 1 오른쪽 끝).
export function orbit(min, rise, set) {
  const day = min >= rise && min < set
  const span = day ? set - rise : 1440 - (set - rise)
  const f = day ? (min - rise) / span : ((min - set + 1440) % 1440) / span
  return { day, f: Math.max(0, Math.min(1, f)) }
}

// o: { min, rise, set, timer(quitTimer 결과 또는 없음), tick(초 단위 위상 — 홀수일 때 깜빡임이 꺼진 쪽), flash(정각 반짝임 위상 — 홀수일 때 밝음) }
// 돌려주는 값은 Raster cells 에 넣을 [글자, 글자색, 바탕색] u32 배열(14 × 2칸).
export function arcWords(o) {
  const cols = ARC_COLS
  const rows = ARC_ROWS
  const W = cols * 2
  const H = rows * 4
  const { day, f } = orbit(o.min, o.rise, o.set)
  const bright = (o.flash || 0) % 2 === 1
  const orb = day ? sunColor(f) : MOON
  const bits = new Array(cols * rows).fill(0)
  const lit = new Array(cols * rows).fill(false)
  const at = (g) => [Math.round(1 + g * (W - 3)), Math.round(H - 1 - Math.sin(Math.PI * g) * (H - 1))]
  for (let i = 0; i <= 80; i += 1) {
    const g = i / 80
    const [x, y] = at(g)
    const k = (y >> 2) * cols + (x >> 1)
    bits[k] |= BRL[y & 3][x & 1]
    if (g <= f) lit[k] = true
  }
  const words = new Uint32Array(cols * rows * 3)
  const put = (c, r, cp, fg) => {
    const k = (r * cols + c) * 3
    words[k] = cp
    words[k + 1] = fg
    words[k + 2] = DEF
  }
  // 지나온 길은 해 · 달 색, 남은 길은 회색. 정각 반짝임의 밝은 위상에서는 길 전체가 켜지고 해가 겹고리(◉)로 커진다
  // (흰색으로 번쩍이면 밝은 바탕에서 안 보인다).
  for (let k = 0; k < cols * rows; k += 1) put(k % cols, Math.floor(k / cols), bits[k] ? 0x2800 + bits[k] : 0x20, lit[k] || bright ? orb : REST)
  const [sx, sy] = at(f)
  put(Math.max(0, Math.min(cols - 1, sx >> 1)), sy >> 2, bright ? 0x25c9 : day ? 0x25cf : 0x25d7, bright ? FLASH : orb)
  const tm = o.timer
  if (tm && !tm.off && tm.text) {
    const odd = (o.tick || 0) % 2 === 1
    const start = Math.floor((cols - tm.text.length) / 2)
    for (let i = 0; i < tm.text.length; i += 1) {
      const ch = tm.text[i]
      // 깜빡임은 마지막 10분(과 퇴근 직후 10분)에만 — 숫자 전체가 꺼졌다 켜진다.
      // 평소에 가운데 점을 매초 깜빡이면 쉬는 세션마다 1초에 한 번씩 그림을 갈아 끼우게 되어 뺐다(부하 실측 2026-10-08).
      const off = odd && tm.blink
      put(start + i, 1, off ? 0x20 : ch.charCodeAt(0), tm.color)
    }
  }
  return words
}

export function arcCells(o) {
  return new Uint8Array(arcWords(o).buffer).toBase64()
}

// Clawd 뒤 하늘. 그림 칸 세 줄의 바탕색 — 위에서 아래로.
// 아침은 아래가 복숭앗빛, 낮은 파랑, 밤은 남색에 달과 별.
// 노을은 처음 그린 안과 다르다 — 그 안의 아래 두 줄(자주 · 주황)은 주황색 Clawd 와 밝기가 같아 몸이 묻혀서, 남보라로 어둡게 깔고 주황은 땅끝 빛줄기(glow)로 옮겼다.
export const SKY = {
  morning: [0x7fb2e8, 0xa9cdf0, 0xffd9a8],
  day: [0x4a9be8, 0x6fb4f0, 0x9ccbf5],
  sunset: [0x2f2f6b, 0x5a3f80, 0x8a4577],
  night: [0x0d1433, 0x141c44, 0x1b2452],
}
export const SKY_PHASES = ['morning', 'day', 'sunset', 'night']
export function skyPhase(min, rise, set) {
  if (min < rise - 30 || min >= set + 55) return 'night'
  if (min < 600) return 'morning'
  return min < set - 80 ? 'day' : 'sunset'
}
// 하늘 위의 해 색. 반원의 해와 달리 바탕이 늘 하늘색이라 밝은 노랑 · 흰빛을 쓸 수 있다.
export function skySunColor(f) {
  return f < 0.07 ? 0xff7d52 : f < 0.22 ? 0xffb84d : f < 0.38 ? 0xffe27a : f < 0.62 ? 0xfff6c2 : f < 0.8 ? 0xffd75f : f < 0.93 ? 0xffa53d : 0xff6336
}
// 돌려주는 값: { phase, rows(줄마다의 바탕색), stars, cloud, glow(노을의 땅끝 빛줄기), orb(해 · 달의 칸 — 반원이 안 보일 때만 그린다) }
export function skyOf(min, rise, set, cols = 15) {
  const phase = skyPhase(min, rise, set)
  let orb
  if (phase === 'night') orb = { cx: cols - 3, cy: 0, ch: '◗', color: 0xffd23f }
  else {
    const f = Math.max(0, Math.min(1, (min - rise) / (set - rise)))
    const cy = phase === 'day' ? 0 : phase === 'morning' ? (min < 480 ? 2 : 1) : min < set - 30 ? 1 : 2
    orb = { cx: Math.round(f * (cols - 1)), cy, ch: '●', color: skySunColor(f) }
  }
  return { phase, rows: SKY[phase], stars: phase === 'night', cloud: phase === 'day' || phase === 'morning', glow: phase === 'sunset', orb }
}

// 잠든 세션(오래 쉰 세션)의 하늘: 시각과 상관없이 밤이고, 반원이 보여도 달을 그린다.
// 달은 왼쪽 위에 둔다 — 오른쪽 위는 잠든 Clawd 의 z 가 올라가는 자리다.
// 달 글자는 노란 반달(◗)이다 — 처음 쓴 반쯤 찬 원 글자는 눈알처럼 보였다. 반원의 달도 같은 글자로 맞췄다(색은 밝은 바탕에서도 읽히는 연보라 그대로).
export function sleepSky() {
  return { phase: 'night', rows: SKY.night, stars: true, cloud: false, glow: false, showOrb: true, orb: { cx: 1, cy: 0, ch: '◗', color: 0xffd23f } }
}

// 퇴근 무렵 Clawd 의 기분. 평일에만 본다.
// 퇴근 5분 전부터 퇴근 5분 뒤까지는 신남(party — 선글라스), 그 뒤 퇴근 1시간 뒤까지는 우울(gloom), 그 밖에는 없음.
// 기본 퇴근 18:00 이면 17:55~18:05 신남 · 18:05~19:00 우울 · 19:00 부터는 평소대로다.
export const MOOD_PARTY_MIN = 5
export const MOOD_END_MIN = 60
export function quitMood(min, dow, end = QUIT_MIN) {
  if (dow === 0 || dow === 6) return ''
  const d = min - end
  if (d >= -MOOD_PARTY_MIN && d < MOOD_PARTY_MIN) return 'party'
  if (d >= MOOD_PARTY_MIN && d < MOOD_END_MIN) return 'gloom'
  return ''
}

// 주간 띠: 평일 다섯 글자. 오늘은 밝게, 지난 날은 흐리게, 남은 날은 더 흐리게. 주말에는 그 요일을 끝에 붙인다.
export function weekSpans(dow) {
  const weekend = dow === 0 || dow === 6
  const out = []
  for (let i = 1; i <= 5; i += 1) out.push({ text: DAY_KO[i], kind: i === dow ? 'today' : i < dow || weekend ? 'past' : 'future' })
  if (weekend) out.push({ text: DAY_KO[dow], kind: 'weekend' })
  return out
}

// 분이 바뀐 순간에 울릴 효과. 정해진 시각(평일)이 정각과 겹치면 종만 친다.
export function chimeAt(min, dow, bells = BELLS_DEFAULT) {
  if (dow >= 1 && dow <= 5 && bells.includes(min)) return 'bell'
  return min % 60 === 0 ? 'hour' : ''
}

files.hooks/poll.js:
// 요소별 폴링 주기와, 폴링으로 읽은 글자를 값으로 바꾸는 순수 로직. `$` 를 받지 않는다.
// 이벤트로 알 수 있는 것(턴 · 툴 · 서브에이전트 · 프롬프트 · 원격 연결)은 폴링하지 않는다. 여기 있는 것은 밖에서 바뀌어 물어봐야만 아는 값이다.

// 초 단위. 자주 바뀌고 싸게 읽히는 것은 촘촘히, 느리게 바뀌거나 비싼 것은 듬성듬성.
export const POLL_DEFAULT = { sys: 5, awake: 30, usage: 60, flags: 5, git: 60, fleet: 30, linear: 600 }
// 이보다 촘촘하게는 받지 않는다(맥 자원 한 번 읽기에 1초가 걸린다).
export const POLL_MIN = { sys: 2, awake: 10, usage: 15, flags: 2, git: 15, fleet: 10, linear: 60 }
export const POLL_LABEL = {
  sys: '맥 자원(CPU · 메모리) — 한 세션만 재고 나머지는 그 값을 읽는다',
  awake: '화면 안 꺼짐(caffeinate) — 한 세션만 잰다',
  usage: '토큰 한도(5h · 7d) — 컨텍스트는 턴마다 이벤트로 받는다',
  flags: '경보 파일 — 이 세션이 만든 것이 있을 때만',
  git: '브랜치 · 변경 수 · 미push — 턴이 끝날 때도 읽는다',
  fleet: '워커 — 워커 기록이 있는 세션일 때만',
  linear: '이슈 제목 — 이슈가 바뀌면 바로 읽는다',
}
// 잠든 세션(오래 쉰 세션)은 주기를 이만큼 늘린다. 경보 파일 확인은 늘리지 않는다.
export const SLEEP_FACTOR = 6

// 저장된 값(없거나 깨진 값 포함)을 기본값 위에 얹고 하한으로 자른다.
export function normalizePoll(saved) {
  const out = Object.assign({}, POLL_DEFAULT)
  if (saved && typeof saved === 'object') {
    for (const k of Object.keys(POLL_DEFAULT)) {
      const v = Number(saved[k])
      if (Number.isFinite(v) && v > 0) out[k] = Math.max(POLL_MIN[k], Math.round(v))
    }
  }
  return out
}

// `/cockpit poll <요소> <초>` 의 한 건. 모르는 요소 · 숫자가 아닌 값은 바꾸지 않고 이유를 돌려준다.
export function setPoll(cur, key, value) {
  if (!(key in POLL_DEFAULT)) return { ok: false, poll: cur, msg: '모르는 요소: ' + key + ' — ' + Object.keys(POLL_DEFAULT).join(' · ') + ' 중에서 고른다' }
  if (value === 'reset' || value === '기본') return { ok: true, poll: Object.assign({}, cur, { [key]: POLL_DEFAULT[key] }), msg: key + ' 를 기본값 ' + POLL_DEFAULT[key] + '초로 되돌렸다' }
  const v = Number(value)
  if (!Number.isFinite(v) || v <= 0) return { ok: false, poll: cur, msg: '초는 0보다 큰 숫자로 적는다 — 예: /cockpit poll sys 3' }
  const sec = Math.max(POLL_MIN[key], Math.round(v))
  const note = sec !== Math.round(v) ? ' (하한 ' + POLL_MIN[key] + '초로 맞춤)' : ''
  return { ok: true, poll: Object.assign({}, cur, { [key]: sec }), msg: key + ' 주기를 ' + sec + '초로 바꿨다' + note }
}

export function pollText(poll) {
  const lines = ['요소별 폴링 주기 — 바꾸기: /cockpit poll <요소> <초> · 되돌리기: /cockpit poll <요소> reset']
  for (const k of Object.keys(POLL_DEFAULT)) lines.push('  ' + k.padEnd(7) + String(poll[k]).padStart(4) + '초' + (poll[k] !== POLL_DEFAULT[k] ? ' (기본 ' + POLL_DEFAULT[k] + ')' : '') + '  ' + POLL_LABEL[k])
  lines.push('폴링하지 않는 것: 작업 중 · 단계 · 도구 수 · 서브에이전트 · 컨텍스트 · 원격 연결 · 세션 이름(이벤트) · 반원 · 퇴근 숫자 · 정각 효과(분이 바뀔 때)')
  return lines.join('\n')
}

export function due(now, last, sec) {
  return !last || now - last >= sec * 1000
}

// 맥 자원을 읽는 명령. iostat 는 1초 동안의 실제 CPU 사용률을, memory_pressure 는 여유 메모리 비율을, sysctl 은 커널의 메모리 압력 단계를 준다.
// ps · top 보다 싸다(한 번에 CPU 13ms쯤 · 실측 2026-10-08).
export const SYS_CMD = '/usr/sbin/iostat -c 2 -w 1 | /usr/bin/tail -1; /usr/bin/memory_pressure -Q | /usr/bin/tail -1; /usr/sbin/sysctl -n kern.memorystatus_vm_pressure_level'

// SYS_CMD 출력 → { cpu(%), memUsed(%), pressure(1 정상 · 2 경고 · 4 위험) }. 읽지 못하면 null.
export function parseSys(text) {
  const lines = String(text || '')
    .split('\n')
    .map((l) => l.trim())
    .filter(Boolean)
  if (lines.length < 2) return null
  // iostat 마지막 줄: … us sy id 1m 5m 15m — 디스크 수에 따라 앞 열 개수가 달라 뒤에서 센다.
  const io = lines[0].split(/\s+/).map(Number)
  if (io.length < 6 || io.some((n) => !Number.isFinite(n))) return null
  const idle = io[io.length - 4]
  const m = /free percentage:\s*(\d+)%/.exec(lines[1])
  if (!m || idle < 0 || idle > 100) return null
  const pressure = lines[2] && /^\d+$/.test(lines[2]) ? Number(lines[2]) : 1
  return { cpu: Math.round(100 - idle), memUsed: 100 - Number(m[1]), pressure }
}

// CPU 는 순간값이 튀므로 직전 값과 반씩 섞어 쓴다(두세 번 연속으로 높아야 단계가 오른다).
export function smoothCpu(prev, cpu) {
  return prev === null || prev === undefined ? cpu : Math.round(prev * 0.5 + cpu * 0.5)
}

// CPU 는 세션을 여는 순간처럼 몇 초씩 튄다. 높음은 80% 이상이 30초, 위험은 95% 이상이 60초 이어질 때만 인정한다.
// hist: 최근 표본 [{ ts, cpu }] (오래된 것부터). 창의 8할 이상을 덮는 표본이 모두 기준을 넘어야 한다.
export function sustain(hist, now) {
  const over = (ms, th) => {
    const w = (hist || []).filter((h) => now - h.ts <= ms)
    return w.length >= 2 && now - w[0].ts >= ms * 0.8 && w.every((h) => h.cpu >= th)
  }
  return { hi: over(30000, 80), crit: over(60000, 95) }
}

// 0 평소 · 1 주의 · 2 높음 · 3 위험. 기준은 확정 시안의 안(案)이다.
// 주의: CPU 50%(직전 값과 섞은 값) 또는 메모리 75% · 높음: CPU 80% 가 30초 또는 메모리 85% 또는 압력 경고 · 위험: CPU 95% 가 60초 또는 메모리 93% 또는 압력 위험.
export function sysLevel(s, cpu, held) {
  if (!s) return 0
  const c = cpu === null || cpu === undefined ? s.cpu : cpu
  const h = held || { hi: false, crit: false }
  if (h.crit || s.memUsed >= 93 || s.pressure >= 4) return 3
  if (h.hi || s.memUsed >= 85 || s.pressure >= 2) return 2
  if (c >= 50 || s.memUsed >= 75) return 1
  return 0
}

// `pmset -g assertions` 출력에서 caffeinate 가 화면 잠자기를 막고 있는지 본다.
// 턴이 도는 동안 Claude Code 가 거는 caffeinate 는 시스템 잠자기만 막으므로(화면은 꺼진다) 여기에 잡히지 않는다.
export function parseAwake(text) {
  return /pid \d+\(caffeinate\):.*PreventUserIdleDisplaySleep/.test(String(text || ''))
}

// 여러 세션이 같은 값을 따로 재지 않게, 캐시 파일을 보고 「이번에는 내가 잰다」를 정한다.
// 마지막으로 잰 세션이 계속 재고, 그 세션이 사라져 값이 주기의 2.2배보다 낡으면 먼저 본 세션이 이어받는다.
export function shouldSample(cache, now, sid, sec) {
  if (!cache || !Number.isFinite(Number(cache.ts))) return true
  const age = now - Number(cache.ts)
  // 재는 데 1초쯤 걸리고 값은 다 잰 뒤에 적히므로, 재던 세션은 주기의 6할만 지나도 다시 잰다(주기를 꽉 채우길 기다리면 간격이 두 배가 된다).
  if (cache.by === sid) return age >= sec * 600
  return age >= sec * 2200
}

files.hooks/config.js:
// 쓰는 사람의 환경에 맞추는 값. `~/.claude/harness-cockpit.json` 을 register.js 가 읽어 setConfig 로 넘긴다.
// 순수 로직 — `$` 를 받지 않는다. 부재 시 동작: 파일이 없으면 아래 기본값으로 돌고, 해당 기능(레포 이름표 · 경보 · 작업 대장 · 워커)만 빠진다.

const DEFAULT_BRANCH_KEY = '[A-Z][A-Z0-9]+-[0-9]+'
const DEFAULT_ISSUE_KEY = '^[A-Z][A-Z0-9]*-[0-9]+$'

function compile(src, flags) {
  if (typeof src !== 'string' || !src) return null
  try {
    return new RegExp(src, flags || '')
  } catch {
    return null
  }
}

function expand(path, home) {
  const p = String(path || '')
  return p.startsWith('~/') ? String(home || '') + p.slice(1) : p
}

const str = (v) => (typeof v === 'string' ? v : '')

// 깨진 항목(정규식 오류 · 빠진 값)은 그 항목만 버린다 — 설정 파일 한 줄 때문에 띠 전체가 멈추면 안 된다.
export function normalizeConfig(raw, home) {
  const r = raw && typeof raw === 'object' ? raw : {}
  const repos = []
  for (const x of Array.isArray(r.repos) ? r.repos : []) {
    const re = compile(x && x.match)
    if (!re) continue
    const family = x.family === 'red' || x.family === 'blue' ? x.family : ''
    repos.push({ re, name: str(x.name), color: str(x.color), family, brand: str(x.brand), word: str(x.word) })
  }
  const alertFiles = []
  for (const x of Array.isArray(r.alertFiles) ? r.alertFiles : []) {
    if (x && typeof x.path === 'string' && x.path.startsWith('/') && str(x.label)) alertFiles.push({ path: x.path, label: x.label })
  }
  const a = r.alert && typeof r.alert === 'object' ? r.alert : {}
  const i = r.issue && typeof r.issue === 'object' ? r.issue : {}
  const cmd = Array.isArray(i.boardCommand) && i.boardCommand.length && i.boardCommand.every((s) => typeof s === 'string' && s) ? i.boardCommand.map((s) => expand(s, home)) : null
  const w = r.serviceWindow && typeof r.serviceWindow === 'object' ? r.serviceWindow : null
  const hour = (v) => (Number.isInteger(v) && v >= 0 && v <= 24 ? v : null)
  const serviceWindow = w && str(w.label) && hour(w.startHour) !== null && hour(w.endHour) !== null && w.startHour < w.endHour ? { label: w.label, start: w.startHour, end: w.endHour } : null
  // "HH:MM" → 자정부터의 분. 틀린 값은 null.
  const hm = (v) => {
    const m = /^([01]?\d|2[0-3]):([0-5]\d)$/.exec(str(v))
    return m ? Number(m[1]) * 60 + Number(m[2]) : null
  }
  const loc = r.location && typeof r.location === 'object' ? r.location : null
  const num = (v, lo, hi) => (typeof v === 'number' && Number.isFinite(v) && v >= lo && v <= hi ? v : null)
  const location = loc && num(loc.lat, -66, 66) !== null && num(loc.lon, -180, 180) !== null ? { lat: loc.lat, lon: loc.lon } : null
  const tx = r.texts && typeof r.texts === 'object' ? r.texts : {}
  return {
    repos,
    alertFiles,
    // 글귀 몇 개는 쓰는 사람의 말버릇에 맞출 수 있다. 없으면 아래 기본 글귀다.
    texts: {
      leftClear: str(tx.leftClear) || '띄운 것 없음 — 세션을 닫아도 된다',
      leftBusy: str(tx.leftBusy) || '닫기 전에 정리한다',
      leftPane: str(tx.leftPane) || '닫기 전 정리 필요',
      boardHint: str(tx.boardHint),
    },
    // 일출 · 일몰을 계산할 위치(위도 · 경도). 없으면 06:00 · 18:00 으로 고정한다.
    location,
    // 퇴근 시각(자정부터의 분)과 종을 칠 시각들(평일). 종은 기본으로 없다.
    quitMin: hm(r.quitTime) === null ? 18 * 60 : hm(r.quitTime),
    bells: (Array.isArray(r.bells) ? r.bells : []).map(hm).filter((v) => v !== null),
    // 「검증」 단계로 볼 명령을 더한다(정규식). 기본 목록(jest · vitest · npm test 등)에 얹는다.
    verifyRe: compile(str(r.verifyCommand)),
    // 평일 정해진 시간대에만 켜지는 것(예: 개발 서버)의 이름과 시간. 시작 효과의 브리핑 카드에 한 줄로 나온다. 없으면 그 줄이 빠진다.
    serviceWindow,
    alert: { title: str(a.title) || '경보 파일', note: str(a.note) },
    branchKeyRe: compile(str(r.branchKey) || DEFAULT_BRANCH_KEY, str(r.branchKey) ? str(r.branchKeyFlags) : '') || compile(DEFAULT_BRANCH_KEY),
    issue: {
      boardCommand: cmd,
      boardLineDir: expand(str(i.boardLineDir), home),
      mcpServer: i.mcpServer === undefined ? 'linear' : str(i.mcpServer),
      keyRe: compile(str(i.keyPattern) || DEFAULT_ISSUE_KEY) || compile(DEFAULT_ISSUE_KEY),
    },
    fleetRoot: expand(str(r.fleetRoot), home),
  }
}

let cfg = normalizeConfig(null, '')

export function setConfig(raw, home) {
  cfg = normalizeConfig(raw, home)
  return cfg
}

export function getConfig() {
  return cfg
}

// `/cockpit config` 가 찍는 한 줄 요약.
export function configText(c, path, found) {
  const n = (list, pick) => list.filter(pick).length
  return [
    '설정 파일 ' + path + (found ? '' : ' — 없음(기본값으로 동작)'),
    '  레포 이름표 ' + n(c.repos, (x) => x.name) + ' · 계열 색 ' + n(c.repos, (x) => x.family) + ' · 시작 효과 이름 ' + n(c.repos, (x) => x.brand || x.word) + ' · 경보 파일 ' + c.alertFiles.length + ' · 가동 시간대 ' + (c.serviceWindow ? c.serviceWindow.label : '없음'),
    '  위치 ' + (c.location ? '설정됨' : '없음(일출 06:00 · 일몰 18:00 고정)') + ' · 퇴근 ' + String(Math.floor(c.quitMin / 60)).padStart(2, '0') + ':' + String(c.quitMin % 60).padStart(2, '0') + ' · 종 ' + (c.bells.length ? c.bells.length + '개' : '없음'),
    '  브랜치 키 /' + c.branchKeyRe.source + '/' + c.branchKeyRe.flags + ' · 작업 대장 명령 ' + (c.issue.boardCommand ? '있음' : '없음') + ' · 이슈 조회 MCP ' + (c.issue.mcpServer || '없음') + ' · 워커 기록 ' + (c.fleetRoot ? '있음' : '없음'),
    '고친 뒤 다시 읽기: /cockpit config reload',
  ].join('\n')
}

files.hooks/fx.js:
// 새 세션 시작 효과 4종의 프레임 그리기. `$` 를 받지 않는다 — 요소 생성자(E) · 재료(ctx) ·
// 경과 시간(ms)만으로 트리를 만든다. 같은 입력이면 같은 프레임이 나온다.
// register.js 가 그린다 — 1번(부팅 스윕)은 띠 자리에서, 나머지는 띠 위에 얹어서. 여러 개를 함께 재생할 수 있다.
// 고르는 법: /fx use 1 4 (기본 1 · /fx off 는 끔).
import { MASCOT } from './mascot.js'
import { getConfig } from './config.js'

// ms 는 미리 보기(/fx N) 재생 길이다. 2번(브리핑)은 새 세션 시작 때는 첫 턴이 시작될 때까지 남는다.
export const FX = {
  1: { name: '부팅 스윕', ms: 2600, note: '띠가 왼쪽부터 켜지고 한도 게이지가 0 에서 차오른다 · 2줄' },
  2: { name: '브리핑 카드', ms: 9000, note: '작업 대장 · 최근 작업 · 가동 시간대(설정했을 때) · 한도를 한 장으로 · 첫 프롬프트에 접힘' },
  3: { name: '캐릭터 인사', ms: 3600, note: '샘플 캐릭터가 통통 튀며 인사 · 3초 뒤 사라짐' },
  4: { name: '워드마크', ms: 2800, note: '레포 이름을 큰 글자로 · 빛이 한 번 지나감 · 레포 색(파랑 / 빨강)' },
}

const DEF = 0x01000000
const DIM = 'inactive'
const ACCENT = { blue: 0x4d9bff, red: 0xff6b80 }
const LEVEL_COLORS = ['success', '#8CC63F', 'warning', '#E8833A', 'error']

function t(E, text, props) {
  return E.Text(Object.assign({ children: [text] }, props || {}))
}

function clamp(x) {
  return Math.max(0, Math.min(1, x))
}

// 빠르게 시작해 천천히 멈추는 곡선.
function ease(x) {
  return 1 - Math.pow(1 - clamp(x), 3)
}

export function mix(a, b, k) {
  const c = (shift) => Math.round(((a >> shift) & 255) + (((b >> shift) & 255) - ((a >> shift) & 255)) * clamp(k))
  return (c(16) << 16) | (c(8) << 8) | c(0)
}

export function hex(n) {
  return '#' + n.toString(16).padStart(6, '0')
}

function toBase64(words) {
  return new Uint8Array(words.buffer).toBase64()
}

function levelColor(p) {
  if (p === null || p === undefined) return DIM
  return LEVEL_COLORS[p >= 85 ? 4 : p >= 70 ? 3 : p >= 50 ? 2 : p >= 30 ? 1 : 0]
}

function gauge(E, label, p, n, k) {
  const shown = p === null || p === undefined ? null : Math.round(p * k)
  const filled = shown === null ? 0 : Math.round((shown / 100) * n)
  const out = [t(E, label + ' ', { color: DIM })]
  for (let i = 0; i < n; i += 1) {
    const at = Math.round(((i + 0.5) / n) * 100)
    out.push(t(E, '▊', { color: i < filled ? levelColor(at) : 'subtle' }))
  }
  out.push(t(E, shown === null ? ' —' : ' ' + shown + '%', { color: levelColor(shown), bold: true }))
  return out
}

// 한글 · 한자 등 넓은 글자는 2칸으로 센다(줄 맞춤용).
export function cellWidth(s) {
  let n = 0
  for (const ch of String(s)) n += ch.codePointAt(0) >= 0x1100 ? 2 : 1
  return n
}

function card(E, color, children) {
  return E.Box({ flexDirection: 'column', borderStyle: 'round', borderColor: color, paddingX: 1, children })
}

function line(E, children) {
  return E.Text({ wrap: 'truncate-end', children })
}

// ── 1. 부팅 스윕 ────────────────────────────────────────────────────────────────
// 앞 0.9초: 빛나는 머리가 왼쪽에서 오른쪽으로 지나가며 선을 켠다. 뒤: 글자가 찍히고 게이지가 차오른다.
export function sweepWords(width, pos, accent) {
  const words = new Uint32Array(width * 3)
  for (let i = 0; i < width; i += 1) {
    const lit = i < pos
    const head = lit && i >= pos - 4
    words[i * 3] = lit ? 0x2501 : 0x2500
    words[i * 3 + 1] = head ? mix(accent, 0xffffff, 0.3 + 0.7 * ((i - (pos - 4)) / 4)) : lit ? accent : 0x3a3a3a
    words[i * 3 + 2] = DEF
  }
  return words
}

function sweep(E, ctx, ms, cols) {
  const accent = ACCENT[ctx.family]
  const width = Math.max(10, Math.min(cols - 4, 110))
  const border = hex(mix(0x3a3a3a, accent, ease(ms / 700)))
  if (ms < 900) {
    const pos = Math.round(ease(ms / 900) * width)
    return card(E, border, [E.Raster({ key: 'fx-sweep', columns: width, rows: 1, cells: toBase64(sweepWords(width, pos, accent)) }), t(E, ' '), ...(ctx.tall ? [t(E, ' ')] : [])])
  }
  const full = '● ' + ctx.name + ' 세션 시작 · ' + ctx.dateText
  const typed = full.slice(0, Math.floor((ms - 900) / 35))
  const k = ease((ms - 900) / 1100)
  const u = ctx.usage
  return card(E, border, [
    line(E, [t(E, typed.slice(0, 1), { color: hex(accent) }), t(E, typed.slice(1), { bold: true })]),
    line(E, [...gauge(E, 'ctx', u.ctx, 8, k), t(E, '   '), ...gauge(E, '5h', u.h5, 6, k), t(E, '   '), ...gauge(E, '7d', u.d7, 6, k)]),
    ...(ctx.tall ? [t(E, ' ')] : []),
  ])
}

// ── 2. 브리핑 카드 ──────────────────────────────────────────────────────────────
// 줄이 0.13초 간격으로 하나씩 펼쳐진다.
function briefing(E, ctx, ms) {
  const accent = hex(ACCENT[ctx.family])
  const b = ctx.board
  const label = (s) => t(E, s + ' '.repeat(Math.max(0, 10 - cellWidth(s))) + ' ', { color: DIM })
  const rows = [
    line(E, [t(E, '세션 브리핑', { bold: true, color: accent }), t(E, '  ' + ctx.dateLong + ' · ' + ctx.name, { color: DIM })]),
    line(E, [
      label('작업 대장'),
      ...(b
        ? [t(E, '이어받을 것 '), t(E, String(b.resume), { bold: true, color: accent }), t(E, ' · 대기 '), t(E, String(b.wait), { bold: true }), ...(getConfig().texts.boardHint ? [t(E, '   ' + getConfig().texts.boardHint, { color: DIM })] : [])]
        : [t(E, '읽지 못함', { color: DIM })]),
    ]),
    line(E, [label('최근 작업'), t(E, b && b.recent.length ? b.recent.map((r) => r.task + (r.issue ? ' (' + r.issue + ')' : '')).join(' · ') : '없음')]),
    ...(ctx.dev ? [line(E, [label(ctx.dev.label), t(E, ctx.dev.open ? '가동 시간대' : '정지 시간대', { color: ctx.dev.open ? 'success' : 'warning', bold: true }), t(E, ' · ' + ctx.dev.text, { color: DIM })])] : []),
    line(E, [label('한도'), ...gauge(E, '5h', ctx.usage.h5, 8, 1), t(E, ctx.usage.h5Reset ? ' ↻' + ctx.usage.h5Reset : '', { color: DIM }), t(E, '   '), ...gauge(E, '7d', ctx.usage.d7, 8, 1)]),
  ]
  return card(E, accent, rows.slice(0, Math.min(rows.length, Math.floor(ms / 130) + 1)))
}

// ── 3. 캐릭터 인사 ──────────────────────────────────────────────────────────────
// 그림 높이 + 1줄을 고정해 두고 빈 줄을 위 · 아래로 옮겨 튀는 모양을 낸다(띠 높이가 흔들리지 않는다).
function mascot(E, ctx, ms, cols, maxRows) {
  const m = maxRows >= 24 ? MASCOT[36] : MASCOT[30]
  const accent = hex(ACCENT[ctx.family])
  const up = Math.floor(ms / 320) % 2 === 0
  const slide = Math.max(0, 14 - Math.floor(ms / 30))
  const pic = E.Raster({ key: 'fx-mascot', columns: m.cols, rows: m.rows, cells: m.cells })
  const hello = '안녕하세요!'.slice(0, Math.floor(ms / 70))
  const words = [t(E, hello, { bold: true, color: accent })]
  if (ms > 1000) words.push(t(E, ctx.dateLong + ' · ' + ctx.name))
  if (ms > 1500 && ctx.board) words.push(t(E, '이어받을 것 ' + ctx.board.resume + ' · 대기 ' + ctx.board.wait, { color: DIM }))
  const pad = []
  for (let i = 0; i < Math.floor(m.rows / 2) - 1; i += 1) pad.push(t(E, ' '))
  return E.Box({
    flexDirection: 'row',
    columnGap: 3,
    paddingLeft: slide,
    children: [
      E.Box({ flexDirection: 'column', flexShrink: 0, children: up ? [pic, t(E, ' ')] : [t(E, ' '), pic] }),
      cols - slide - m.cols >= 24 ? E.Box({ flexDirection: 'column', children: [...pad, ...words] }) : null,
    ],
  })
}

// ── 4. 워드마크 ────────────────────────────────────────────────────────────────
// 3×5 점 글꼴. 점 하나를 2칸(██)으로 그려 5줄짜리 큰 글자를 만든다.
const FONT = {
  A: '010101111101101', B: '110101110101110', C: '011100100100011', D: '110101101101110', E: '111100110100111',
  F: '111100110100100', G: '011100101101011', H: '101101111101101', I: '111010010010111', J: '001001001101010',
  K: '101101110101101', L: '100100100100111', M: '101111111101101', N: '110101101101101', O: '111101101101111',
  P: '110101110100100', Q: '010101101111011', R: '110101110101101', S: '111100111001111', T: '111010010010010',
  U: '101101101101111', V: '101101101101010', W: '101101111111101', X: '101101010101101', Y: '101101010010010',
  Z: '111001010100111', '-': '000000111000000',
}

// 반환: { cols, rows: 5, on(x, y) } — 글자 사이 한 점 띄움, 점 하나는 scale 칸.
export function wordGrid(text, scale) {
  const letters = [...text.toUpperCase()].filter((c) => FONT[c])
  const dots = Math.max(0, letters.length * 4 - 1)
  return {
    cols: dots * scale,
    rows: 5,
    on(x, y) {
      const dx = Math.floor(x / scale)
      const li = Math.floor(dx / 4)
      const cx = dx % 4
      if (cx === 3 || li >= letters.length) return false
      return FONT[letters[li]][y * 3 + cx] === '1'
    },
  }
}

export function wordmarkWords(text, scale, ms, accent) {
  const g = wordGrid(text, scale)
  const words = new Uint32Array(g.cols * g.rows * 3)
  const shown = ease(ms / 700) * g.cols
  const span = g.cols + 24
  const center = -12 + span * clamp((ms - 500) / 1500)
  for (let y = 0; y < g.rows; y += 1) {
    for (let x = 0; x < g.cols; x += 1) {
      const w = (y * g.cols + x) * 3
      const lit = g.on(x, y) && x < shown
      // 빛은 오른쪽 위에서 왼쪽 아래로 기울어 지나간다.
      const glow = clamp(1 - Math.abs(x + y * 1.5 - center) / 9)
      words[w] = lit ? 0x2588 : 0x20
      words[w + 1] = lit ? mix(accent, 0xffffff, glow * 0.9) : DEF
      words[w + 2] = DEF
    }
  }
  return { cols: g.cols, rows: g.rows, words }
}

function wordmark(E, ctx, ms, cols) {
  const accent = ACCENT[ctx.family]
  const scale = wordGrid(ctx.word, 2).cols <= cols - 2 ? 2 : 1
  const r = wordmarkWords(ctx.word, scale, ms, accent)
  const sub = ms > 800 ? '세션 시작 · ' + ctx.dateText : ' '
  return E.Box({
    flexDirection: 'column',
    paddingLeft: 1,
    children: [E.Raster({ key: 'fx-word', columns: r.cols, rows: r.rows, cells: toBase64(r.words) }), t(E, sub, { color: DIM })],
  })
}

// 저장된 값(숫자 하나 · 배열 · 없음)을 효과 번호 배열로 고른다. 0 과 빈 배열은 「끔」이다.
// 부재 시 동작: 값이 없거나 알 수 없는 모양이면 fallback 을 쓴다.
export function normalizeChoice(value, fallback) {
  if (value === 0) return []
  const list = Array.isArray(value) ? value : typeof value === 'number' ? [value] : null
  if (!list) return fallback.slice()
  const out = []
  for (const v of list) if (FX[v] && !out.includes(v)) out.push(v)
  return out.length || list.length === 0 ? out : fallback.slice()
}

// 명령 인자에서 효과 번호를 뽑는다. "1 3" · "1,3" · "13" 모두 [1, 3].
export function parseIds(text) {
  const out = []
  for (const ch of String(text || '')) {
    const n = Number(ch)
    if (FX[n] && !out.includes(n)) out.push(n)
  }
  return out
}

// 여러 효과를 함께 재생할 때 지금 무엇을 그릴지 정한다.
// keep: 새 세션 시작 재생 — 브리핑(2)은 첫 턴이 시작될 때까지 남는다. 미리 보기는 각자 정해진 길이만 재생한다.
// 반환: above = 띠 위에 얹을 효과(위에서 아래 순서) · sweep = 띠 자리에서 부팅 스윕을 그릴지 ·
//       moving = 아직 움직이는 중인지 · done = 더 그릴 것이 없는지
export function introLayout(ids, ms, keep) {
  const on = (id) => ids.includes(id) && (ms < FX[id].ms || (id === 2 && keep))
  const above = [3, 4, 2].filter(on)
  const sweep = on(1)
  const moving = ids.some((id) => ms < (id === 2 && keep ? 1200 : FX[id].ms))
  return { above, sweep, moving, done: !sweep && above.length === 0 }
}

// 아직 켜지지 않은 띠. 새 세션인지 정해지기 전 잠깐 그린다(부팅 스윕의 0초 모습과 같은 크기).
// tall: 띠에 Clawd 가 있어 3줄일 때.
export function bootCard(E, tall) {
  return card(E, 'subtle', tall ? [t(E, ' '), t(E, ' '), t(E, ' ')] : [t(E, ' '), t(E, ' ')])
}

export function draw(E, id, ctx, ms, cols, maxRows) {
  if (id === 1) return sweep(E, ctx, ms, cols)
  if (id === 2) return briefing(E, ctx, ms)
  if (id === 3) return mascot(E, ctx, ms, cols, maxRows)
  return wordmark(E, ctx, ms, cols)
}

// ── 재료 만들기(순수) ───────────────────────────────────────────────────────────
// `wip` 명령의 출력에서 요약 숫자와 위쪽 작업 3개를 뽑는다. 형식이 다르면 null.
export function parseBoard(text) {
  const m = /이어받을 것\s*\**(\d+)\**\s*·\s*대기\s*\**(\d+)/.exec(text || '')
  if (!m) return null
  const recent = []
  for (const row of String(text).split('\n')) {
    if (!/^\|\s*\d+\s*\|/.test(row)) continue
    const c = row.split('|').map((s) => s.trim())
    const task = (c[3] || '').replace(/\*\*/g, '')
    const issue = (c[4] || '').replace(/^-$/, '')
    if (task) recent.push({ task: task.length > 22 ? task.slice(0, 21) + '…' : task, issue: issue.split(',')[0].trim() })
    if (recent.length === 3) break
  }
  return { resume: Number(m[1]), wait: Number(m[2]), recent }
}

// 평일 정해진 시간대에만 켜져 있는 것(설정의 serviceWindow — 예: 개발 서버)이 지금 가동 시간대인지. 실제 응답 여부가 아니라 시간대만 말한다.
// 부재 시 동작: 설정이 없으면 null 이고 브리핑 카드에서 그 줄이 빠진다.
export function devWindow(d, win) {
  const w = win === undefined ? getConfig().serviceWindow : win
  if (!w) return null
  const p = (n) => String(n).padStart(2, '0')
  const span = '평일 ' + p(w.start) + '–' + w.end + '시'
  const day = d.getDay()
  const h = d.getHours()
  const weekday = day >= 1 && day <= 5
  if (weekday && h >= w.start && h < w.end) {
    const left = (w.end - h) * 60 - d.getMinutes()
    return { label: w.label, open: true, text: span + ' · 정지까지 ' + Math.floor(left / 60) + '시간 ' + (left % 60) + '분' }
  }
  const next = weekday && h < w.start ? '오늘' : day >= 1 && day <= 4 ? '내일' : '월요일'
  return { label: w.label, open: false, text: span + ' · 다음 가동 ' + next + ' ' + p(w.start) + ':00' }
}

const DAYS = ['일', '월', '화', '수', '목', '금', '토']

export function dateTexts(d) {
  const p = (n) => String(n).padStart(2, '0')
  const hm = p(d.getHours()) + ':' + p(d.getMinutes())
  return {
    dateText: p(d.getMonth() + 1) + '-' + p(d.getDate()) + ' (' + DAYS[d.getDay()] + ') ' + hm,
    dateLong: d.getMonth() + 1 + '월 ' + d.getDate() + '일 (' + DAYS[d.getDay()] + ') ' + hm,
  }
}

// 시작 효과(워드마크 · 인사)에 쓰는 이름. 설정의 repos 중 brand · word 가 있는 첫 항목을 따르고, 없으면 폴더 이름이다.
export function repoOf(cwd) {
  const c = String(cwd || '')
  for (const x of getConfig().repos) {
    if ((x.brand || x.word) && x.re.test(c)) return { family: x.family || 'blue', name: x.brand || x.word, word: x.word || x.brand.toUpperCase() }
  }
  const base = c.split('/').filter(Boolean).pop() || 'CLAUDE'
  return { family: 'blue', name: base, word: base.toUpperCase().replace(/[^A-Z-]/g, '').slice(0, 12) || 'CLAUDE' }
}

