// 바탕화면 샘플.jpeg 를 미리 칸 그림으로 구워 둔 값(Raster cells). 실행 중에는 그림 파일을 읽지 않는다.
// 배경은 터미널 기본색으로 비우고 캐릭터 둘레 1픽셀만 흰색으로 남겼다. 크기별 { cols, rows, cells }.
export const MASCOT = {
  30: { cols: 30, rows: 15, cells: '' },
  36: { cols: 36, rows: 18, cells: '' },
}
